window#waybar {
    background: transparent;
}


.modules-left,
.modules-center,
.modules-right{
    background: rgba(30, 30, 46, 0.85);
    border-radius: 8px;
    margin: 6px 4px;
    padding: 4px 8px;
}

/* :not(.taskbar) keeps this off the taskbar module's active button */
#workspaces:not(.taskbar) button.active {
    background-image: url('/home/krubics/.config/waybar/assets/pixelated-pokeball.png');
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
    background-origin: content-box; /* inset the ball from the accent pill's edges */
    background-color: #89b4fa;
    color: transparent; /* hides the workspace number behind the pokeball */
    padding: 0px 4px;
    min-width: 22px;
    min-height: 0px;
    margin: 4px 0px;
    border-radius: 5px;
}

#custom-taskbar-divider,
#custom-divider {
    color: rgba(255, 255, 255, 0.25);
    margin: 0 6px;
}

#workspaces.taskbar button {
    min-width: 0;
    min-height: 0;
    padding: 0;
    margin: 0;
    border: none;
    background: transparent;
}

#workspaces.taskbar .taskbar-window {
    padding: 2px 4px;
    margin: 0 2px;
    border-radius: 5px;
}

#workspaces.taskbar .taskbar-window:hover {
    background: rgba(137, 180, 250, 0.3);
}

#custom-clock-icon {
    background-image: url('/home/krubics/Downloads/right-facing-pixelated-dialga.png');
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
    padding-left: 20px;
    margin-left: 10px;
}

